window.MG_LAZY_DATA["data/lazy/owner-resources/b483-af3584b8d61c979b.json"]={sha256:"af3584b8d61c979b9ad53ce6ea3f16d5f1795ec9d4c52426b2024ea36e143ff6",value:{"sources":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-waste-fabric","title":"EPA 袋濾防制技術監測","titleEn":"EPA Monitoring by Control Technique: Fabric Filters","url":"https://www.epa.gov/air-emissions-monitoring-knowledge-base/monitoring-control-technique-fabric-filters","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-control","title":"EPA 空氣污染防制成本手冊","titleEn":"EPA Air Pollution Control Cost Manual","url":"https://www.epa.gov/economic-and-cost-analysis-air-pollution-regulations/cost-reports-and-guidance-air-pollution","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"media":{"courses":[{"courseId":"b483","videos":[],"guides":[{"id":"b483-v17-practice","title":"工程操作與定量驗證手冊","titleEn":"Engineering actions and quantitative verification","concept":"本課以「由濾餅、配流與差壓理解袋濾除塵與破袋診斷」為主軸，依序處理入口粉塵負荷、濾餅累積與阻力、出口濃度與去除率、破袋事件的時間延遲、分室診斷可信度。十個單元各包含機制、算例、量測驗證及失效診斷；數值均為明示的原創教學假設，不能直接用作工程設計、排放限值或設備設定。","conceptEn":"This course focuses on Understand bag filtration and failure diagnosis through cake, flow distribution and differential pressure, progressing through Inlet dust loading, Cake accumulation and resistance, Outlet concentration and removal, Timing of a bag-failure signal, Confidence in compartment diagnosis. Ten units each address mechanism, worked calculation, measurement verification and failure diagnosis. Numbers are explicit original teaching assumptions, not design values, emission limits or equipment settings.","procedure":["只將 Q 改成 12000 Nm³/h，其餘輸入固定。重算結果應由 0.2 變成 0.24 kg/h。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將可用面積 A 降為 100 m²，其餘輸入固定。重算結果應由 0.5 變成 0.6 m/min。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 p1 改成 2200 Pa，其餘輸入固定。重算結果應由 1200 變成 1600 Pa。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 Δp 改成 1800 Pa，其餘輸入固定。重算結果應由 3 變成 4.5 kW。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 Cout 改成 20 mg/m³，其餘輸入固定。重算結果應由 88 變成 80 %。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將量測 O₂ 改成 12%，其餘輸入固定。重算結果應由 45.4545 變成 55.5556 mg/Nm³ at assumed reference。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 q 改成 0.8 L/min，其餘輸入固定。重算結果應由 4 變成 2.5 min。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 n 改成 1200，其餘輸入固定。重算結果應由 91.6667 變成 83.3333 %。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 uC 改成 0.03，其餘輸入固定。重算結果應由 0.072111 變成 0.05 relative standard uncertainty。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。","只將 t 改成 90 h，其餘輸入固定。重算結果應由 94 變成 91 %。先預測方向，再核對單位與假設；用離線模擬或已提供資料完成，不操作現場設備。"],"procedureEn":["Change only Q to 12000 Nm³/h, holding all other inputs fixed. Recalculation changes 0.2 to 0.24 kg/h. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Reduce only available area A to 100 m², holding all other inputs fixed. Recalculation changes 0.5 to 0.6 m/min. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only p1 to 2200 Pa, holding all other inputs fixed. Recalculation changes 1200 to 1600 Pa. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only Δp to 1800 Pa, holding all other inputs fixed. Recalculation changes 3 to 4.5 kW. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only Cout to 20 mg/m³, holding all other inputs fixed. Recalculation changes 88 to 80 %. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only measured O₂ to 12%, holding all other inputs fixed. Recalculation changes 45.4545 to 55.5556 mg/Nm³ at assumed reference. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only q to 0.8 L/min, holding all other inputs fixed. Recalculation changes 4 to 2.5 min. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only valid intervals n to 1200, holding all other inputs fixed. Recalculation changes 91.6667 to 83.3333 %. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only uC to 0.03, holding all other inputs fixed. Recalculation changes 0.072111 to 0.05 relative standard uncertainty. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment.","Change only downtime to 90 h, holding all other inputs fixed. Recalculation changes 94 to 91 %. Predict the direction first, then check units and assumptions; use offline simulation or supplied data without operating field equipment."],"evidence":["針對「入口粉塵負荷」，查驗溫壓、含濕率及濃度報表欄位，再核對煙道流速與面積。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「濾布面積與過濾風速」，核對在線濾袋數、實際氣量與分室差壓，辨識局部超載。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「濾餅累積與阻力」，檢查導壓管、零點和測點位置，再把差壓與流量趨勢一起畫出。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「清灰週期與能耗」，量測風量、差壓與輸入功率，在同一運轉點核對效率。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「出口濃度與去除率」，同步採入口與出口並校正相同基準，另核對出口量測不確定度。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「溫壓乾濕基與氧校正」，保存原始濃度、含濕與 O₂，再重算每項校正，防止對已校正數據重複校正。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「破袋事件的時間延遲」，以安全參考訊號或離線脈衝重播測全系統響應，不只使用分析儀規格。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「監測失效與缺測」，畫出缺值時間軸並保留校正、維護與通訊錯誤旗標，禁止把缺值填成零。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「分室診斷可信度」，建立每項不確定度來源表，將重複性、校正和代表性分開，檢查相關性。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。","針對「維修隔離與備援容量」，對照事件紀錄、備援切換和品質資料，分開統計不可用及不合格時間。 保存原始資料、單位與校正日期，以本步模型和另一種可能原因比較。"],"evidenceEn":["For Inlet dust loading, Check temperature, pressure, moisture and concentration-report bases, then verify duct velocity and area. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Cloth area and filtration velocity, Check online bag count, actual gas flow and compartment pressure drop to identify local overloading. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Cake accumulation and resistance, Inspect impulse lines, zero and tap locations, then plot pressure drop with flow. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Cleaning cycles and energy, Measure airflow, differential pressure and input power at the same operating point. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Outlet concentration and removal, Sample inlet and outlet simultaneously on the same basis and assess outlet measurement uncertainty. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Reference conditions and oxygen correction, Retain raw concentration, moisture and O₂ and recompute corrections to avoid double normalization. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Timing of a bag-failure signal, Use a safe reference signal or offline pulse replay to measure whole-system response, not analyzer specifications alone. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Monitor failure and data gaps, Plot missing intervals with calibration, maintenance and communication flags; never replace missing values with zero. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Confidence in compartment diagnosis, Build an uncertainty budget separating repeatability, calibration and representativeness; inspect correlations. Retain raw data, units and calibration date; compare the model with one alternative explanation.","For Maintenance isolation and backup capacity, Compare event logs, backup switching and quality data, separating unavailable and nonconforming periods. Retain raw data, units and calibration date; compare the model with one alternative explanation."],"pitfalls":["標準氣量和實際體積流量混乘會系統性偏差。 在「入口粉塵負荷」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","把停用濾袋計入面積，會低估在線風速。 在「濾布面積與過濾風速」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","導壓管堵塞可能被誤判為設備阻塞。 在「濾餅累積與阻力」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","堵塞使壓降上升，若只提高風機轉速可能增加能耗而不解決配流。 在「清灰週期與能耗」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","不同基準直接相減或用低於檢出限數值當零，會誇大效率。 在「出口濃度與去除率」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","接近空氣氧含量時分母很小，微小氧誤差會放大。 在「溫壓乾濕基與氧校正」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","管線冷凝或吸附會造成較長且不對稱的拖尾。 在「破袋事件的時間延遲」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","高污染時停機造成選擇性缺值，可偏低估平均污染。 在「監測失效與缺測」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","增加同偏差的重複測量不能消除系統性誤差。 在「分室診斷可信度」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。","設備在線但數據失效或處理不合格時，不能當作完整有效服務。 在「維修隔離與備援容量」的流程圖圈出錯誤可能進入的位置，再指定能區分原因的量測。"],"pitfallsEn":["Multiplying standard concentration by actual volume flow creates systematic bias. Mark where this error can enter the Inlet dust loading flow and name a measurement that distinguishes causes.","Counting unavailable bags understates online filtration velocity. Mark where this error can enter the Cloth area and filtration velocity flow and name a measurement that distinguishes causes.","A blocked impulse line can be mistaken for equipment blockage. Mark where this error can enter the Cake accumulation and resistance flow and name a measurement that distinguishes causes.","Blockage raises pressure drop; speed increases may waste energy without correcting distribution. Mark where this error can enter the Cleaning cycles and energy flow and name a measurement that distinguishes causes.","Subtracting different bases or treating nondetects as zero exaggerates efficiency. Mark where this error can enter the Outlet concentration and removal flow and name a measurement that distinguishes causes.","Near ambient oxygen the denominator is small and minor oxygen errors amplify strongly. Mark where this error can enter the Reference conditions and oxygen correction flow and name a measurement that distinguishes causes.","Condensation or adsorption in tubing causes longer asymmetric tails. Mark where this error can enter the Timing of a bag-failure signal flow and name a measurement that distinguishes causes.","Outages during high pollution cause selective missingness and can bias the average downward. Mark where this error can enter the Monitor failure and data gaps flow and name a measurement that distinguishes causes.","Repeating measurements with the same bias does not remove systematic error. Mark where this error can enter the Confidence in compartment diagnosis flow and name a measurement that distinguishes causes.","An online unit with invalid data or nonconforming treatment is not fully effective service. Mark where this error can enter the Maintenance isolation and backup capacity flow and name a measurement that distinguishes causes."],"sourceIds":["v17s-waste-fabric","v17s-waste-control","v17s-waste-wi"],"sources":[{"id":"v17s-waste-fabric","title":"EPA 袋濾防制技術監測","titleEn":"EPA Monitoring by Control Technique: Fabric Filters","url":"https://www.epa.gov/air-emissions-monitoring-knowledge-base/monitoring-control-technique-fabric-filters","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-control","title":"EPA 空氣污染防制成本手冊","titleEn":"EPA Air Pollution Control Cost Manual","url":"https://www.epa.gov/economic-and-cost-analysis-air-pollution-regulations/cost-reports-and-guidance-air-pollution","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"simulationOnly":true,"scope":"公開原理與資料支持的原創教學。算例中的輸入為明示教學假設，非該設施實測或操作設定。此處任務在離線模型完成，不能作為現場設計、飲用水合格或設備操作許可。","scopeEn":"Original teaching based on public principles and sources. Numerical inputs are explicit teaching assumptions, not site measurements or operating setpoints. Tasks use offline models and do not certify field design, potable-water compliance or equipment operation."}]}]},"related":{"courses":[{"courseId":"b483","overview":"跨單元連結與比較練習","overviewEn":"Cross-process connections and comparisons","related":[{"id":"b484","title":"煙氣脫硝系統","titleEn":"Flue-gas denitrification systems","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"教學參考區域：美國北卡羅來納研究三角園區（非本課實拍場址）","nameEn":"Reference region: Research Triangle Park, North Carolina (not a photographed course facility)","country":"美國","countryEn":"United States","lat":35.9,"lon":-78.9,"scope":"Approximate institutional reference region; not a facility entrance, installation location or visitor permission.","lng":-78.9,"coordinateScope":"公開設施或研究據點的近似代表位置；不是操作入口或實際教學實驗室。","coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]},{"id":"b485","title":"煙氣酸性氣體洗滌","titleEn":"Acid-gas scrubbing of flue gas","why":"比較兩個系統的物質或能量收支，列出不可直接沿用的邊界條件。","whyEn":"Compare material or energy balances and identify boundary conditions that cannot be transferred.","transfer":"守恆、量測與失效驗證","transferEn":"Conservation, measurement and failure verification","difference":"設備尺度、進料組成與品質目標必須分別設定。","differenceEn":"Equipment scale, feed composition and quality objectives require separate definitions.","practice":["各選一個教學算例，記下輸入、輸出與單位。","對照兩課的系統邊界，說明哪些假設不能沿用。","改變一個輸入，提出量測與失效判據來核對結果。"],"practiceEn":["Choose one worked example from each course and record inputs, outputs and units.","Compare system boundaries and identify assumptions that cannot transfer.","Change one input and propose measurements and failure criteria to check the result."],"place":{"name":"教學參考區域：美國北卡羅來納研究三角園區（非本課實拍場址）","nameEn":"Reference region: Research Triangle Park, North Carolina (not a photographed course facility)","country":"美國","countryEn":"United States","lat":35.9,"lon":-78.9,"scope":"Approximate institutional reference region; not a facility entrance, installation location or visitor permission.","lng":-78.9,"coordinateScope":"公開設施或研究據點的近似代表位置；不是操作入口或實際教學實驗室。","coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"referenceUrls":["https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","https://www.epa.gov/smm","https://www.epa.gov/septic/wastewater-technology-fact-sheets"]}],"references":[{"id":"b-src-environment","title":"Research on Innovative and Alternative Wastewater Technologies","url":"https://www.epa.gov/sustainable-water-infrastructure/research-innovative-and-alternative-wastewater-technologies","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: wastewater technologies and treatment references. Not individual verification of every named environmental project."},{"id":"b-src-waste","title":"Sustainable Materials Management","url":"https://www.epa.gov/smm","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: materials life cycles, waste prevention, recycling and recovery."},{"id":"b-src-wastewater","title":"Wastewater Technology Fact Sheets","url":"https://www.epa.gov/septic/wastewater-technology-fact-sheets","publisher":"U.S. Environmental Protection Agency","scope":"Category overview: disinfection, constructed wetlands, package plants, sewer technologies and treatment."},{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-control","title":"EPA 空氣污染防制成本手冊","titleEn":"EPA Air Pollution Control Cost Manual","url":"https://www.epa.gov/economic-and-cost-analysis-air-pollution-regulations/cost-reports-and-guidance-air-pollution","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-fabric","title":"EPA 袋濾防制技術監測","titleEn":"EPA Monitoring by Control Technique: Fabric Filters","url":"https://www.epa.gov/air-emissions-monitoring-knowledge-base/monitoring-control-technique-fabric-filters","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}]}]},"places":{"courses":[{"courseId":"b483","place":{"name":"教學參考區域：美國北卡羅來納研究三角園區（非本課實拍場址）","nameEn":"Reference region: Research Triangle Park, North Carolina (not a photographed course facility)","country":"美國","countryEn":"United States","lat":35.9,"lon":-78.9,"scope":"Approximate institutional reference region; not a facility entrance, installation location or visitor permission.","lng":-78.9,"coordinateScope":"公開設施或研究據點的近似代表位置；不是操作入口或實際教學實驗室。","coordinateScopeEn":"Approximate public facility/research reference, not an operating entrance or the teaching laboratory."},"summary":"這項技術的學習脈絡由單一設備處理，逐步擴展至物質與能量收支、監測品質和生命週期比較。本課將官方方法文件作為查核入口，並以獨立編寫的假想數據練習；參考文件的年代與地區不代表其規範在所有場址適用。","summaryEn":"The learning progression expands from individual treatment equipment to mass and energy balances, monitoring quality and lifecycle comparison. Official method documents provide verification starting points while independently authored hypothetical data support practice; a document date or jurisdiction does not establish applicability to every site.","history":[{"year":"工程背景","title":"焚化煙氣袋濾除塵","titleEn":"Fabric-filter flue-gas cleaning","text":"這項技術的學習脈絡由單一設備處理，逐步擴展至物質與能量收支、監測品質和生命週期比較。本課將官方方法文件作為查核入口，並以獨立編寫的假想數據練習；參考文件的年代與地區不代表其規範在所有場址適用。","textEn":"The learning progression expands from individual treatment equipment to mass and energy balances, monitoring quality and lifecycle comparison. Official method documents provide verification starting points while independently authored hypothetical data support practice; a document date or jurisdiction does not establish applicability to every site."}],"connection":"本課以「由濾餅、配流與差壓理解袋濾除塵與破袋診斷」為主軸，依序處理入口粉塵負荷、濾餅累積與阻力、出口濃度與去除率、破袋事件的時間延遲、分室診斷可信度。十個單元各包含機制、算例、量測驗證及失效診斷；數值均為明示的原創教學假設，不能直接用作工程設計、排放限值或設備設定。","connectionEn":"This course focuses on Understand bag filtration and failure diagnosis through cake, flow distribution and differential pressure, progressing through Inlet dust loading, Cake accumulation and resistance, Outlet concentration and removal, Timing of a bag-failure signal, Confidence in compartment diagnosis. Ten units each address mechanism, worked calculation, measurement verification and failure diagnosis. Numbers are explicit original teaching assumptions, not design values, emission limits or equipment settings.","references":[{"id":"v17s-waste-fabric","title":"EPA 袋濾防制技術監測","titleEn":"EPA Monitoring by Control Technique: Fabric Filters","url":"https://www.epa.gov/air-emissions-monitoring-knowledge-base/monitoring-control-technique-fabric-filters","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-control","title":"EPA 空氣污染防制成本手冊","titleEn":"EPA Air Pollution Control Cost Manual","url":"https://www.epa.gov/economic-and-cost-analysis-air-pollution-regulations/cost-reports-and-guidance-air-pollution","organization":"US EPA","accessed":"2026-10-23","publisher":"US EPA","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."},{"id":"v17s-waste-wi","title":"歐盟 JRC 廢棄物焚化 BREF（2019）","titleEn":"JRC Waste Incineration BREF (2019)","url":"https://publications.jrc.ec.europa.eu/repository/handle/JRC118637","organization":"European Commission Joint Research Centre","accessed":"2026-10-23","publisher":"European Commission Joint Research Centre","scope":"來源支持原理或工程背景；算例為明示教學假設。","scopeEn":"Source supports principles or project context; examples use explicit teaching assumptions."}],"sourceIds":["v17s-waste-fabric","v17s-waste-control","v17s-waste-wi"]}]},"vendors":{"courses":[],"vendors":[]}}};
